    ch = paper[i]
    if re.match(r"[\s\u00a0\u2009\u202f\u2007]", ch):
        j = i
        while j < len(paper) and re.match(r"[\s\u00a0\u2009\u202f\u2007]", paper[j]):
            j += 1
        npos_to_orig[k] = (i, j)
